# owner: platform
import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines

def shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start * 60, end * 60))

BUSY = [
    shift("Ana", 9, 10),
    shift("Bo", 9, 17),
    shift("Ana", 9, 11, "tue")
]

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines(BUSY)
        self.assertEqual(lines, [
            "Bo: 1 shifts, 8.0 hours",
            "Ana: 2 shifts, 3.0 hours"
        ])

    def test_one_decimal_place(self):
        odd = Shift("Ana", "mon", Span(540, 595))
        lines = timesheet_lines([odd])
        expected = ["Ana: 1 shifts, 0.9 hours"]
        self.assertEqual(lines, expected)

    def test_ties_sorted_by_name(self):
        lines = timesheet_lines([
            shift("Zed", 9, 10),
            shift("Amy", 9, 10)
        ])
        self.assertTrue(lines[0].startswith("Amy"))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker(self):
        for name in ("", "   "):
            with self.assertRaises(ProjectError):
                timesheet_lines([shift(name, 9, 10)])
